SELECT order_id,region,quantity*unit_price*(1-discount_pct) AS net_revenue
FROM orders WHERE status='Completed' AND quantity*unit_price*(1-discount_pct)>10000
ORDER BY net_revenue DESC LIMIT 10;

SELECT region,COUNT(DISTINCT order_id) AS orders,
ROUND(SUM(quantity*unit_price*(1-discount_pct)),2) AS net_revenue
FROM orders WHERE status='Completed' GROUP BY region ORDER BY net_revenue DESC;

SELECT o.order_id,o.customer_id,c.segment,
o.quantity*o.unit_price*(1-o.discount_pct) AS net_revenue
FROM orders o LEFT JOIN customers c ON o.customer_id=c.customer_id;

